!! Golden comparison of the thickness pieces against the Icepack column physics:
!! `freeboard`, the relayering block of `thickness_changes` and
!! `update_state_vthermo`, each on about thirty columns with nilyr in
!! {1, 2, 4, 7, 8}.
!!
!! The tables are 17-significant-digit literals from the Icepack oracle.
!! `freeboard` and `update_state_vthermo` are the upstream routines called
!! directly; the relayering block is inline in `thickness_changes`, so the oracle
!! drives a verbatim text copy of that block (including the upstream
!! `adjust_enthalpy`).  The comparison therefore covers the block's setup (layer
!! depths, `hilyr`, the `hin <= 0` clamp) and the overlap integral, not
!! `thickness_changes` as a whole.  The Icepack and CESM constant sets agree on
!! `rhoi`, `rhos`, `rhow`, `puny` (the only constants these routines read), so
!! the tables are identical for the two and the test asserts that equality and
!! then checks both sets.
!!
!! Tolerance.  CPU builds: exact (`RTOL = ATOL = 0`); the measured worst
!! difference on gfortran (FMA contraction off) is 0, bitwise on every row, as
!! the port forms the same expressions in the same order.  GPU build
!! (`RDB_GPU_OFFLOAD`, FMA contraction on for host code too): relative 1e-12;
!! the measured GPU-build worst is 3.3e-16 relative (stated at `RTOL`).
module test_cice_golden_thickness_pieces
   use, intrinsic :: iso_fortran_env, only: int32
   use, intrinsic :: ieee_arithmetic, only: ieee_is_finite
   use testdrive, only: new_unittest, unittest_type, error_type, test_failed
   use rdb_constants, only: wp
   use rdb_ice_params, only: ice_constants_t, ice_constants, ICE_CONSTANTS_ICEPACK, ICE_CONSTANTS_CESM
   use rdb_ice_thickness, only: ice_freeboard, ice_relayer, ice_update_state_vthermo
   implicit none
   private

   public :: collect_cice_golden_thickness_pieces_tests

#ifdef RDB_GPU_OFFLOAD
   real(wp), parameter :: RTOL = 1.0e-12_wp
      !! GPU build (FMA on): relative; measured worst on the GPU build 3.3e-16 relative.
   real(wp), parameter :: ATOL = 1.0e-300_wp
      !! Absolute floor (exact zeros must match to this).
#else
   real(wp), parameter :: RTOL = 0.0_wp
      !! CPU builds: exact (measured worst 0 on gfortran).
   real(wp), parameter :: ATOL = 0.0_wp
      !! CPU builds: exact.
#endif

