contains

   subroutine collect_cice_golden_thickness_pieces_tests(testsuite)
      type(unittest_type), allocatable, intent(out) :: testsuite(:)
      testsuite = [ &
                  new_unittest("constant_sets_agree_on_inputs", test_sets_agree), &
                  new_unittest("freeboard_vs_icepack_icepack_set", test_fb_icepack), &
                  new_unittest("freeboard_vs_icepack_cesm_set", test_fb_cesm), &
                  new_unittest("relayer_vs_icepack_icepack_set", test_rl_icepack), &
                  new_unittest("relayer_vs_icepack_cesm_set", test_rl_cesm), &
                  new_unittest("update_state_vs_icepack", test_up) &
                  ]
   end subroutine collect_cice_golden_thickness_pieces_tests

   subroutine cmp(error, label, got, ref, n)
      !! Finite-first comparison of `got(1:n)` against `ref(1:n)`.
      type(error_type), allocatable, intent(inout) :: error
      character(len=*), intent(in) :: label
      integer, intent(in) :: n
      real(wp), intent(in) :: got(n), ref(n)
      integer :: i
      character(len=200) :: msg
      if (allocated(error)) return
      do i = 1, n
         if (.not. ieee_is_finite(got(i))) then
            write (msg, '(a,a,i0)') trim(label), ": non-finite at ", i
            call test_failed(error, trim(msg))
            return
         end if
         if (abs(got(i) - ref(i)) > ATOL + RTOL*abs(ref(i))) then
            write (msg, '(a,a,i0,2(a,es24.16))') trim(label), ": index ", i, " got ", got(i), " ref ", ref(i)
            call test_failed(error, trim(msg))
            return
         end if
      end do
   end subroutine cmp

   subroutine test_sets_agree(error)
      type(error_type), allocatable, intent(out) :: error
      type(ice_constants_t) :: a, b
      a = ice_constants(ICE_CONSTANTS_ICEPACK)
      b = ice_constants(ICE_CONSTANTS_CESM)
      if (a%rhoi /= b%rhoi .or. a%rhos /= b%rhos .or. a%rhow /= b%rhow .or. a%puny /= b%puny) then
         call test_failed(error, "constant sets differ on rhoi/rhos/rhow/puny: the shared tables are invalid")
      end if
   end subroutine test_sets_agree

   subroutine test_fb_icepack(error)
      type(error_type), allocatable, intent(out) :: error
      call run_fb(error, ice_constants(ICE_CONSTANTS_ICEPACK))
   end subroutine test_fb_icepack

   subroutine test_fb_cesm(error)
      type(error_type), allocatable, intent(out) :: error
      call run_fb(error, ice_constants(ICE_CONSTANTS_CESM))
   end subroutine test_fb_cesm

   subroutine test_rl_icepack(error)
      type(error_type), allocatable, intent(out) :: error
      call run_rl(error, ice_constants(ICE_CONSTANTS_ICEPACK))
   end subroutine test_rl_icepack

   subroutine test_rl_cesm(error)
      type(error_type), allocatable, intent(out) :: error
      call run_rl(error, ice_constants(ICE_CONSTANTS_CESM))
   end subroutine test_rl_cesm

   subroutine test_up(error)
      type(error_type), allocatable, intent(out) :: error
      call run_up(error)
   end subroutine test_up

   subroutine run_fb(error, c)
      type(error_type), allocatable, intent(out) :: error
      type(ice_constants_t), intent(in) :: c
      integer, parameter :: W = 43, NR = 32
      integer :: r, n, o
      integer(int32) :: ierr
      real(wp) :: hin, hsn, dzi(8), dzs(1), zqin(8), zqsn(1), snoice, dsnow, got(21), ref(21)
      character(len=24) :: lab
      do r = 1, NR
         o = (r - 1)*W
         n = nint(FB_ROWS(o + 1))
         hin = FB_ROWS(o + 2); hsn = FB_ROWS(o + 3)
         dzi = FB_ROWS(o + 4:o + 11); zqin = FB_ROWS(o + 12:o + 19)
         zqsn(1) = FB_ROWS(o + 20); snoice = FB_ROWS(o + 21); dsnow = FB_ROWS(o + 22)
         dzs(1) = hsn
         ierr = 0_int32
         call ice_freeboard(n, 1, c, hin, hsn, zqin(1:n), zqsn, dzi(1:n), dzs, snoice, dsnow, ierr)
         got = [hin, hsn, dzi(1:8), zqin(1:8), dzs(1), snoice, dsnow]
         ref = FB_ROWS(o + 23:o + 43)
         write (lab, '(a,i0)') "freeboard row ", r
         call cmp(error, trim(lab), got, ref, 21)
         if (allocated(error)) return
         if (ierr /= 0_int32) then
            call test_failed(error, "freeboard: ierr set on finite input")
            return
         end if
      end do
   end subroutine run_fb

   subroutine run_rl(error, c)
      type(error_type), allocatable, intent(out) :: error
      type(ice_constants_t), intent(in) :: c
      integer, parameter :: W = 33, NR = 40
      integer :: r, n, o
      integer(int32) :: ierr
      real(wp) :: hin, hsn, dzi(8), dzs(1), zqin(8), zqsn(1), hilyr, hslyr, got(13), ref(13)
      character(len=24) :: lab
      do r = 1, NR
         o = (r - 1)*W
         n = nint(RL_ROWS(o + 1))
         hin = RL_ROWS(o + 2); hsn = RL_ROWS(o + 3)
         dzi = RL_ROWS(o + 4:o + 11); zqin = RL_ROWS(o + 12:o + 19); zqsn(1) = RL_ROWS(o + 20)
         dzs(1) = hsn
         ierr = 0_int32
         call ice_relayer(n, 1, c, dzi(1:n), dzs, hin, hsn, zqin(1:n), zqsn, hilyr, hslyr, ierr)
         got = [hin, hsn, hilyr, hslyr, zqin(1:8), zqsn(1)]
         ref = RL_ROWS(o + 21:o + 33)
         write (lab, '(a,i0)') "relayer row ", r
         call cmp(error, trim(lab), got, ref, 13)
         if (allocated(error)) return
         if (ierr /= 0_int32) then
            call test_failed(error, "relayer: ierr set on finite input")
            return
         end if
      end do
   end subroutine run_rl

   subroutine run_up(error)
      type(error_type), allocatable, intent(out) :: error
      integer, parameter :: W = 30, NR = 32
      integer :: r, n, o
      integer(int32) :: ierr
      real(wp) :: Tf, Tsf, hin, hsn, aicen, vicen, vsnon, zqin(8), zqsn(1), got(13), ref(13)
      character(len=24) :: lab
      do r = 1, NR
         o = (r - 1)*W
         n = nint(UP_ROWS(o + 1))
         Tf = UP_ROWS(o + 2); Tsf = UP_ROWS(o + 3); hin = UP_ROWS(o + 4); hsn = UP_ROWS(o + 5)
         aicen = UP_ROWS(o + 6); vicen = UP_ROWS(o + 7); vsnon = UP_ROWS(o + 8)
         zqin = UP_ROWS(o + 9:o + 16); zqsn(1) = UP_ROWS(o + 17)
         ierr = 0_int32
         call ice_update_state_vthermo(n, 1, Tf, hin, hsn, Tsf, zqin(1:n), zqsn, aicen, vicen, vsnon, ierr)
         got = [Tsf, aicen, vicen, vsnon, zqin(1:8), zqsn(1)]
         ref = UP_ROWS(o + 18:o + 30)
         write (lab, '(a,i0)') "update row ", r
         call cmp(error, trim(lab), got, ref, 13)
         if (allocated(error)) return
         if (ierr /= 0_int32) then
            call test_failed(error, "update_state: ierr set on finite input")
            return
         end if
      end do
   end subroutine run_up

end module test_cice_golden_thickness_pieces
